// Youth (0-14%) Color Scale
const youthColorScale = [
  { value: 5, color: '#e6f2ff' },
  { value: 10, color: '#99d9ff' },
  { value: 15, color: '#4db8ff' },
  { value: 20, color: '#0099ff' },
  { value: 25, color: '#0066cc' },
  { value: 35, color: '#003d7a' }
];

// Elderly (65+%) Color Scale
const elderlyColorScale = [
  { value: 5, color: '#fffacd' },
  { value: 10, color: '#ffd700' },
  { value: 15, color: '#ffb347' },
  { value: 20, color: '#ff8c00' },
  { value: 25, color: '#ff4500' },
  { value: 35, color: '#8b0000' }
];

function getYouthColor(value) {
  if (value === null || value === undefined || value < 0) return null;
  
  for (let i = youthColorScale.length - 1; i >= 0; i--) {
    if (value >= youthColorScale[i].value) {
      return youthColorScale[i].color;
    }
  }
  return youthColorScale[0].color;
}

function getElderlyColor(value) {
  if (value === null || value === undefined || value < 0) return null;
  
  for (let i = elderlyColorScale.length - 1; i >= 0; i--) {
    if (value >= elderlyColorScale[i].value) {
      return elderlyColorScale[i].color;
    }
  }
  return elderlyColorScale[0].color;
}

function createYouthAgeLayer(geojsonData) {
  return L.geoJSON(geojsonData, {
    style: (feature) => {
      const cellId = feature.properties.id || feature.properties.ime_celice;
      const ageData = ageGridData[cellId];
      
      if (!ageData) {
        return { fill: false, opacity: 0 };
      }
      
      const value = ageData.pct_p00_14;
      if (value === undefined || value === null || value < 0) {
        return { fill: false, opacity: 0 };
      }
      
      const color = getYouthColor(value);
      if (!color) {
        return { fill: false, opacity: 0 };
      }
      
      return {
        fillColor: color,
        weight: 0.3,
        opacity: 0.9,
        color: '#999',
        fillOpacity: 0.85
      };
    },
    onEachFeature: (feature, layer) => {
      const cellId = feature.properties.id || feature.properties.ime_celice;
      const ageData = ageGridData[cellId];
      
      if (ageData && ageData.pct_p00_14 && ageData.pct_p00_14 > 0) {
        const popup = `<div style="font-size:12px;"><strong>${cellId}</strong><br>Youth (0-14%): ${ageData.pct_p00_14.toFixed(1)}%</div>`;
        layer.bindPopup(popup);
      }
    }
  });
}

function createElderlyAgeLayer(geojsonData) {
  return L.geoJSON(geojsonData, {
    style: (feature) => {
      const cellId = feature.properties.id || feature.properties.ime_celice;
      const ageData = ageGridData[cellId];
      
      if (!ageData) {
        return { fill: false, opacity: 0 };
      }
      
      const value = ageData.pct_p65_;
      if (value === undefined || value === null || value < 0) {
        return { fill: false, opacity: 0 };
      }
      
      const color = getElderlyColor(value);
      if (!color) {
        return { fill: false, opacity: 0 };
      }
      
      return {
        fillColor: color,
        weight: 0.3,
        opacity: 0.9,
        color: '#999',
        fillOpacity: 0.85
      };
    },
    onEachFeature: (feature, layer) => {
      const cellId = feature.properties.id || feature.properties.ime_celice;
      const ageData = ageGridData[cellId];
      
      if (ageData && ageData.pct_p65_ && ageData.pct_p65_ > 0) {
        const popup = `<div style="font-size:12px;"><strong>${cellId}</strong><br>Elderly (65+%): ${ageData.pct_p65_.toFixed(1)}%</div>`;
        layer.bindPopup(popup);
      }
    }
  });
}
